<script lang="ts">import FieldRoot from'@fex/components-svelte/primitive/field';import Field from'@fex/components-svelte/primitive/form-field';import FieldControl from'@fex/components-svelte/primitive/field-control';import FieldLabel from'@fex/components-svelte/primitive/field-label';import Form from'@fex/components-svelte/primitive/form';import{createForm}from'@fex/components-svelte/primitive/form/create-form';import Transfer from'@fex/components-svelte/primitive/transfer';import Button from'@fex/components-svelte/ui/button';import Card from'@fex/components-svelte/ui/card';import{fieldNames,members}from'./data';const form=createForm(()=>({defaultValues:{members:[]as readonly(string|number)[]},onSubmit:()=>undefined}))</script>
<Card title="Form validation states" description="Submit the real Form empty to see the error state; selecting exactly one member shows the warning style."><Form {form} class="space-y-space-lg"><Field name="members" validators={{onSubmit:({value}:{value:readonly(string|number)[]})=>value.length===0?'Select at least one member.':undefined}}>{#snippet children(field)}{@const errors=field.state.meta.errors.map(String)}{@const invalid=errors.length>0}<FieldRoot {invalid} hasError={invalid}><FieldLabel>Project members</FieldLabel><FieldControl>{#snippet children(binding)}<Transfer {...binding.props} items={members} {fieldNames} targetKeys={field.state.value} onChange={keys=>field.handleChange(keys)} validation={invalid?{status:'error',message:errors[0]}:field.state.value.length===1?{status:'warning',message:'Only one member is assigned; consider adding a backup.'}:undefined}/>{/snippet}</FieldControl></FieldRoot>{/snippet}</Field><Button type="submit">{#snippet children()}Validate assignment{/snippet}</Button></Form></Card>
